        if (raw == null) return false;
        String t = raw.trim().toUpperCase();
        if (t.length() < 6) return false;
        if (t.length() > 12) return false;
        int i = 0;
        int letters = 0;
        int digits = 0;
        while (i < t.length()) {
            char c = t.charAt(i);
            if (c >= 'A' && c <= 'Z') letters++;
            else if (c >= '0' && c <= '9') digits++;
