public class SimpleCache {
    private String[] k;
    private String[] v;
    private int n;

    public SimpleCache(int cap) {
        if (cap < 1) cap = 1;
        k = new String[cap];
        v = new String[cap];
        n = 0;
    }

    public void put(String key, String val) {
        if (key == null) return;
        for (int i = 0; i < n; i++) {
            if (k[i].equals(key)) {
                v[i] = val;
                return;
            }
        }
        if (n >= k.length) {
            for (int i = 1; i < n; i++) {
                k[i - 1] = k[i];
                v[i - 1] = v[i];
            }
            n = n - 1;
        }
        k[n] = key;
        v[n] = val;
        n = n + 1;
    }

    public String get(String key) {
        if (key == null) return null;
        for (int i = 0; i < n; i++) {
            if (k[i].equals(key)) return v[i];
        }
        return null;
    }
}

