package study.math;

public class InvoiceMath {
    public static double total(double[] prices, double[] qty, double tax) {
        if (prices == null || qty == null) return 0;
        int m = prices.length;
        if (qty.length < m) m = qty.length;
        double s = 0;
        for (int i = 0; i < m; i++) {
            double p = prices[i];
            double q = qty[i];
            if (p < 0) p = 0;
            if (q < 0) q = 0;
            double line = p * q;
            if (tax > 0) {
                line = line + (line * tax);
            }
            s = s + line;
        }
        return Math.round(s * 100.0) / 100.0;
    }
}

