public class InvoiceCalculator {
    public static double calculateTotal(double[] prices, double[] quantities, double taxRate) {
        if (prices == null || quantities == null) {
            return 0;
        }

        int numberOfItems = Math.min(prices.length, quantities.length);
        double subtotal = 0;

        for (int i = 0; i < numberOfItems; i++) {
            double price = Math.max(prices[i], 0);
            double quantity = Math.max(quantities[i], 0);
            double lineItem = calculateLineItem(price, quantity, taxRate);
            subtotal += lineItem;
        }

        return roundToTwoDecimalPlaces(subtotal);
    }

    private static double calculateLineItem(double price, double quantity, double taxRate) {
        double lineItem = price * quantity;
        if (taxRate > 0) {
            lineItem += lineItem * taxRate;
        }
        return lineItem;
    }

    private static double roundToTwoDecimalPlaces(double value) {
        return Math.round(value * 100.0) / 100.0;
    }
}

