package study.finance;

public class Installment {
    public static double[] calculateInstallmentPlan(double principalAmount, int numberOfMonths, double interestRate) {
        numberOfMonths = Math.max(numberOfMonths, 1);
        principalAmount = Math.max(principalAmount, 0);
        interestRate = Math.max(interestRate, 0);

        double[] monthlyPayments = new double[numberOfMonths];
        double remainingBalance = principalAmount;

        for (int month = 0; month < numberOfMonths; month++) {
            double interestCharge = calculateInterest(remainingBalance, interestRate);
            double principalPayment = calculatePrincipalPayment(principalAmount, numberOfMonths);
            double monthlyPayment = principalPayment + interestCharge;

            monthlyPayments[month] = roundToTwoDecimalPlaces(monthlyPayment);
            remainingBalance -= principalPayment;
            remainingBalance = Math.max(remainingBalance, 0);
        }

        return monthlyPayments;
    }

    private static double calculateInterest(double balance, double interestRate) {
        return balance * interestRate;
    }

    private static double calculatePrincipalPayment(double principalAmount, int numberOfMonths) {
