    public static List<String> filterLogLines(String[] logLines, String logLevel) {
        if (logLines == null || logLevel == null) {
            return new ArrayList<>();
        }

        String targetLogLevel = logLevel.trim().toUpperCase();
        List<String> filteredLines = new ArrayList<>();

        for (String logLine : logLines) {
            if (logLine == null) {
                continue;
