            String upperCaseLogLine = logLine.toUpperCase();
            if (isMatchingLogLevel(upperCaseLogLine, targetLogLevel)) {
                filteredLines.add(logLine);
            }
        }

        return filteredLines;
    }

    private static boolean isMatchingLogLevel(String logLine, String targetLogLevel) {
        return logLine.contains("[" + targetLogLevel + "]") || logLine.startsWith(targetLogLevel + ":");
    }
}

