public class WindowCount {
    public static int countValuesAboveThreshold(int[] data, int start, int end, int threshold) {
        if (data == null) {
            return 0;
        }

        start = Math.max(0, start);
        end = Math.min(data.length, end);

        if (start > end) {
            swap(start, end);
        }

        return countValuesAboveThresholdInRange(data, start, end, threshold);
    }

    private static void swap(int start, int end) {
        int temp = start;
        start = end;
        end = temp;
    }

    private static int countValuesAboveThresholdInRange(int[] data, int start, int end, int threshold) {
        int count = 0;
        for (int i = start; i < end; i++) {
            if (data[i] > threshold) {
                count++;
            }
        }
        return count;
    }
}

