public class Checksum {
    public static int rolling(String data, int mod) {
        if (data == null) return 0;
        if (mod < 2) mod = 256;
        int s = 0;
        for (int i = 0; i < data.length(); i++) {
            s = (s + data.charAt(i)) % mod;
            s = (s * 31) % mod;
        }
        return s;
    }
}

