public class Checksum {
    private static final int DEFAULT_MODULUS = 256;
    private static final int PRIME_MULTIPLIER = 31;

    public static int calculateRollingChecksum(String data, int modulus) {
        if (data == null) {
            return 0;
        }
        if (modulus < 2) {
            modulus = DEFAULT_MODULUS;
        }
        return calculateChecksum(data, modulus);
    }

    private static int calculateChecksum(String data, int modulus) {
        int checksum = 0;
        for (char character : data.toCharArray()) {
            checksum = updateChecksum(checksum, character, modulus);
        }
        return checksum;
    }

    private static int updateChecksum(int checksum, char character, int modulus) {
        int newChecksum = (checksum + character) % modulus;
        return (newChecksum * PRIME_MULTIPLIER) % modulus;
    }
}

