            if (isExactMatch(trimmedAllowedIp, trimmedIpAddress)) {
                return true;
            }
        }
        return false;
    }

    private static boolean isWildcardMatch(String ip) {
        return ip.equals("*");
    }

    private static boolean isPrefixMatch(String allowedIp, String ipAddress) {
        return allowedIp.endsWith(".*") && ipAddress.startsWith(allowedIp.substring(0, allowedIp.length() - 1));
    }

    private static boolean isExactMatch(String allowedIp, String ipAddress) {
        return allowedIp.equals(ipAddress);
    }
}

